consultas_censo.comando:
SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN 1 ELSE 0 END) AS total_urbana, 
       SUM(CASE WHEN TP_LOCALIZACAO = '1' THEN 1 ELSE 0 END) AS total_rural 
FROM matriculas;

SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN QT_MAT_BAS END) AS total_escolas_urbanas,
       SUM(CASE WHEN TP_LOCALIZACAO = '1' THEN QT_MAT_BAS END) AS total_escolas_rurais
FROM matriculas;

SELECT SUM(QT_MAT_BAS) AS total_matrículas_urbanas, 
       SUM(QT_MAT_BAS) - SUM(QT_MAT_BAS) WHERE TP_LOCALIZACAO = '2' AS total_matrículas_rurais
FROM matriculas;

SELECT AVG(QT_MAT_BAS) AS media_urbana
FROM matriculas
WHERE TP_LOCALIZACAO = '2' AND CO_REGIAO_GEOG_INTERM IS NOT NULL;

SELECT AVG(QT_MAT_BAS) AS media_rural
FROM matriculas
WHERE TP_LOCALIZACAO = '1' AND CO_REGIAO_GEOG_INTERM IS NOT NULL;

SELECT AVG(SUM(QT_MAT_BAS)) AS media_matrículas_urbana
FROM matriculas
WHERE NO_REGIAO IS NOT NULL AND TRIM(NO_REGIAO) <> '';

SELECT AVG(SUM(QT_MAT_BAS)) AS media_matrículas_rural
FROM matriculas
WHERE NO_REGIAO IS NULL OR TRIM(NO_REGIAO) = '';

